import { useId } from "react";
import type { ChangeEvent, FormEvent, KeyboardEvent } from "react";
import "./CommandBox.css";

export interface CommandReply {
  text: string;
  isError: boolean;
}

export interface CommandBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  placeholder?: string;
  reply?: CommandReply;
}

export function CommandBox({
  value,
  onChange,
  onSubmit,
  placeholder = "Type a command…",
  reply,
}: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  function handleChange(event: ChangeEvent<HTMLInputElement>): void {
    onChange(event.target.value);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const command = value.trim();
    if (command.length === 0) {
      return;
    }
    onSubmit(command);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>): void {
    // Escape clears the input when it has content, so the keyboard user can reset quickly.
    if (event.key === "Escape" && value.length > 0) {
      event.preventDefault();
      onChange("");
    }
  }

  const replyClassName = reply
    ? `command-box__reply${reply.isError ? " command-box__reply--error" : ""}`
    : undefined;

  return (
    <form className="command-box" onSubmit={handleSubmit}>
      <label htmlFor={inputId} className="command-box__label">
        Command
      </label>
      <input
        id={inputId}
        type="text"
        className="command-box__input"
        value={value}
        placeholder={placeholder}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        autoComplete="off"
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck={false}
        aria-describedby={reply ? replyId : undefined}
      />
      {reply && (
        <div
          id={replyId}
          className={replyClassName}
          role={reply.isError ? "alert" : "status"}
        >
          {reply.text}
        </div>
      )}
    </form>
  );
}
